DO $$
DECLARE owner_id uuid:=gen_random_uuid();worker uuid:=gen_random_uuid();company uuid;task uuid:=gen_random_uuid();owner_session uuid:=gen_random_uuid();result jsonb;
  service uuid:=gen_random_uuid();required_task uuid:=gen_random_uuid();checks jsonb;
BEGIN
  PERFORM set_config('request.jwt.claim.sub','',true);PERFORM set_config('request.jwt.claim.role','service_role',true);PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
  INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES(owner_id,'tasks-owner-'||owner_id||'@example.test','{"nome_completo":"Tasks owner","razao_social":"Tasks fixture"}');
  SELECT tenant_id INTO company FROM public.profiles WHERE id=owner_id;
  INSERT INTO auth.users(id,email,raw_user_meta_data,raw_app_meta_data) VALUES(worker,'tasks-worker-'||worker||'@example.test','{"nome_completo":"Tasks worker"}',jsonb_build_object('gestio_employee',true,'gestio_criado_por',owner_id,'gestio_tenant_id',company,'gestio_setor','corte'));
  PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);PERFORM set_config('request.jwt.claim.role','authenticated',true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated','session_id',owner_session)::text,true);
  PERFORM public.autorizar_dispositivo(gen_random_uuid(),'Tasks owner');
  PERFORM public.tarefa_criar(task,'corte','Conferir peças','Conferir medidas',worker);
  result:=public.tarefa_criar(task,'corte','Conferir peças','Conferir medidas',worker);
  IF result->>'repetida'<>'true' OR (SELECT count(*) FROM private.workforce_tasks WHERE id=task)<>1 THEN RAISE EXCEPTION 'Tarefa duplicada'; END IF;
  BEGIN PERFORM public.tarefa_criar(task,'corte','Título diferente','Conferir medidas',worker);RAISE EXCEPTION 'Reutilizou requisição com outros dados';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  BEGIN PERFORM public.tarefa_criar(gen_random_uuid(),'montagem','Tarefa indevida','',worker);RAISE EXCEPTION 'Atribuiu setor não autorizado';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM public.tarefa_criar(gen_random_uuid(),'corte','','',worker);RAISE EXCEPTION 'Título vazio aceito';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  INSERT INTO public.servicos(id,tenant_id,nome,created_by) VALUES(service,company,'Mandatory task service',owner_id);
  PERFORM public.ficha_servico_salvar(service,'corte','{}',0);
  PERFORM public.ficha_execucao_atualizar(service,'corte','iniciar',1);
  PERFORM public.tarefa_criar(required_task,'corte','Tarefa obrigatória','Conferência necessária',worker,service,NULL,'alta',true);
  SELECT jsonb_object_agg(c->>'key',true) INTO checks FROM private.workforce_sheet_templates t,jsonb_array_elements(t.definition->'checklist') c WHERE t.setor='corte' AND t.versao=1;
  PERFORM public.ficha_checklist_salvar(service,'corte',checks,2);
  BEGIN PERFORM public.ficha_execucao_atualizar(service,'corte','concluir',3);RAISE EXCEPTION 'Concluiu etapa com tarefa pendente';EXCEPTION WHEN object_not_in_prerequisite_state THEN NULL;END;
  PERFORM set_config('request.jwt.claim.sub',worker::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',worker,'role','authenticated','session_id',gen_random_uuid())::text,true);
  PERFORM public.autorizar_dispositivo(gen_random_uuid(),'Tasks worker');
  result:=public.minhas_tarefas();
  IF jsonb_array_length(result->'itens')<>2 THEN RAISE EXCEPTION 'Tarefas atribuídas não exibidas'; END IF;
  IF public.ficha_servico_consultar(service,'corte')->>'servico_id'<>service::text THEN RAISE EXCEPTION 'Tarefa não liberou consulta técnica autorizada'; END IF;
  result:=public.ficha_servico_consultar(service,'corte');
  IF result->>'pode_editar'<>'false' OR result->'acoes_execucao'<>'[]'::jsonb THEN RAISE EXCEPTION 'Consulta técnica anunciou ações indevidas'; END IF;
  IF jsonb_array_length(public.minhas_fichas_servicos(0,'')->'itens')<>1 THEN RAISE EXCEPTION 'Ficha da tarefa não apareceu na lista'; END IF;
  BEGIN PERFORM public.ficha_servico_salvar(service,'corte','{"maquina":"Escalation"}',3);RAISE EXCEPTION 'Tarefa liberou edição da ficha';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM public.ficha_execucao_atualizar(service,'corte','pausar',3);RAISE EXCEPTION 'Tarefa liberou controle da etapa';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  result:=public.tarefa_consultar(task);
  IF result->>'id'<>task::text OR result ? 'requisicao' THEN RAISE EXCEPTION 'Detalhe da tarefa inválido'; END IF;
  result:=public.minhas_notificacoes();
  IF jsonb_array_length(result->'itens')<>2 OR EXISTS(SELECT 1 FROM jsonb_array_elements(result->'itens') n WHERE n->>'evento'<>'tarefa_atribuida' OR n->>'tarefa_id' IS NULL) THEN RAISE EXCEPTION 'Notificações de tarefas incompletas'; END IF;
  IF public.meu_resumo_operacional()->'tarefas'->>'total'<>'2' OR public.meu_resumo_operacional()->'tarefas'->>'pendentes'<>'2' THEN RAISE EXCEPTION 'Indicadores pessoais incorretos'; END IF;
  BEGIN PERFORM public.tarefa_criar(gen_random_uuid(),'corte','Não autorizado','',worker);RAISE EXCEPTION 'Funcionário criou tarefa sem permissão';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM public.tarefa_atualizar(task,'concluida',1);RAISE EXCEPTION 'Concluiu tarefa sem iniciar';EXCEPTION WHEN object_not_in_prerequisite_state THEN NULL;END;
  PERFORM public.tarefa_atualizar(task,'em_andamento',1,20,'Conferência iniciada');
  BEGIN PERFORM public.tarefa_atualizar(task,'pausada',1);RAISE EXCEPTION 'Versão antiga aceita';EXCEPTION WHEN serialization_failure THEN NULL;END;
  PERFORM public.tarefa_atualizar(task,'pausada',2,20,'Pausa técnica');
  PERFORM public.tarefa_atualizar(task,'aguardando_material',3,20,'Aguardando reposição');
  PERFORM public.tarefa_atualizar(task,'em_andamento',4,50,'Material recebido');
  result:=public.tarefa_atualizar(task,'concluida',5,NULL,'Conferência concluída');
  IF result->>'progresso'<>'100' OR result->>'concluida_em' IS NULL THEN RAISE EXCEPTION 'Conclusão inconsistente'; END IF;
  BEGIN PERFORM public.tarefa_atualizar(task,'em_andamento',6);RAISE EXCEPTION 'Reabriu tarefa sem aprovação';EXCEPTION WHEN object_not_in_prerequisite_state THEN NULL;END;
  PERFORM public.tarefa_atualizar(required_task,'em_andamento',1);
  PERFORM public.tarefa_atualizar(required_task,'concluida',2);
  IF public.meu_resumo_operacional()->'tarefas'->>'concluidas'<>'2' THEN RAISE EXCEPTION 'Indicadores não refletiram conclusões'; END IF;
  result:=public.minhas_atividades();
  IF jsonb_array_length(result->'itens')=0 THEN RAISE EXCEPTION 'Histórico pessoal não exibido'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(result->'itens') item JOIN public.audit_logs a ON a.id=(item->>'id')::bigint WHERE a.actor_id<>worker OR item ? 'detalhes') THEN
    RAISE EXCEPTION 'Histórico revelou outro ator ou conteúdo sensível';
  END IF;
  PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated','session_id',owner_session)::text,true);
  PERFORM public.ficha_execucao_atualizar(service,'corte','concluir',3);
  IF public.meu_resumo_operacional()->'tarefas'->>'total'<>'0' THEN RAISE EXCEPTION 'Resumo pessoal incluiu tarefas de outro funcionário'; END IF;
END;
$$;
SELECT 'PASS: criação idempotente e acesso individual às tarefas' AS result;
